pm.test("Diary response matches schema", () => {
    const body = pm.response.json();

    pm.expect(body.diaryRecords).to.be.an("array");
    pm.expect(body.diaryAllTags).to.be.an("array");

    body.diaryRecords.forEach(record => {
        pm.expect(record).to.have.all.keys(
            "id_record", "id_user", "title", "date", "created_at"
        );
    });
});

pm.test("Records are sorted by created_at, newest first", function () {
    const times = pm.response.json().diaryRecords.map(function (r) { return new Date(r.created_at).getTime(); });
    const sorted = times.slice().sort(function (a, b) { return b - a; });
    pm.expect(times).to.eql(sorted);
});

