const setCookies = [];
pm.response.headers.each(function (h) {
    if (h.key.toLowerCase() === "set-cookie") {
        setCookies.push(h.value);
    }
});

pm.test("access_token cookie is cleared", function () {
    const c = setCookies.find(function (v) { return v.indexOf("access_token=") === 0; });
    pm.expect(c, "access_token Set-Cookie header").to.be.a("string");
    pm.expect(c).to.match(/^access_token=;/);
});

pm.test("refresh_token cookie is cleared", function () {
    const c = setCookies.find(function (v) { return v.indexOf("refresh_token=") === 0; });
    pm.expect(c, "refresh_token Set-Cookie header").to.be.a("string");
    pm.expect(c).to.match(/^refresh_token=;/);
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Content-Type is application/json", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

pm.test("Message is \"Account deleted\"", function () {
    pm.expect(pm.response.json().message).to.eql("Account deleted");
});

pm.test("access_token is cleared", () => {
    const val = pm.cookies.get("access_token");
    pm.expect(val === "undefined" || val === undefined).to.be.true;
});

pm.test("refresh_token is cleared", () => {
    const val = pm.cookies.get("refresh_token");
    console.log(val)
    pm.expect(val === "undefined" || val === undefined).to.be.true;
});

